                        </div>
                        <div className="flex items-center gap-3 text-sm text-slate-600 font-bold group/phone" dir="ltr">
                          <div className="p-2 bg-slate-100 rounded-xl group-hover/phone:bg-white group-hover/phone:shadow-sm transition-all border border-transparent group-hover/phone:border-slate-100">
                            <Phone size={16} className="text-slate-400 group-hover/phone:text-indigo-600" />
                          </div>
