                <div className="relative group">
                  <img src={formData.photo} alt="Preview" className="w-32 h-32 rounded-[2.5rem] object-cover ring-8 ring-indigo-50 shadow-2xl group-hover:scale-105 transition-transform cursor-pointer" />
                  <button type="button" className="absolute -bottom-2 -right-2 p-3 bg-indigo-600 text-white rounded-2xl shadow-xl hover:bg-indigo-700 transition-all active:scale-90 border-4 border-white">
                    <Camera size={20} />
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-2">الاسم الكامل</label>
                  <input 
                    required
                    type="text" 
                    placeholder="مثال: أستاذ مراد"
