            >
              <Plus size={22} />
              <span className="font-bold">إضافة معلم</span>
            </button>
          </div>
        </div>

        {/* Table Section */}
        <div className="overflow-x-auto">
          <table className="w-full text-right">
            <thead>
              <tr className="bg-slate-50/80 text-slate-500 text-xs font-bold uppercase tracking-widest border-b border-slate-100">
                <th className="px-8 py-5 text-right w-32">المعلم</th>
                <th className="px-8 py-5">المعلومات المهنية</th>
                <th className="px-8 py-5">التواصل الإلكتروني</th>
                <th className="px-8 py-5 text-center">التحكم</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredTeachers.map((teacher) => {
                const subjectStyle = getSubjectStyle(teacher.subject);
                return (
                  <tr key={teacher.id} className="hover:bg-indigo-50/30 transition-all group">
                    <td className="px-8 py-6 whitespace-nowrap">
                      <div className="relative inline-block">
                        <img 
                          src={teacher.photo} 
                          alt={teacher.name} 
                          className="w-20 h-20 rounded-[1.75rem] object-cover ring-4 ring-white shadow-xl group-hover:scale-105 transition-transform duration-300"
                        />
                        <div className="absolute -top-2 -right-2 bg-emerald-500 text-white p-1 rounded-full border-4 border-white shadow-sm">
                          <BadgeCheck size={14} />
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6 whitespace-nowrap">
                      <div className="flex flex-col gap-2">
                        <div>
                          <div className="font-black text-slate-800 text-xl group-hover:text-indigo-700 transition-colors leading-tight">{teacher.name}</div>
                          <div className="text-[10px] font-bold text-slate-400 mt-0.5 tracking-wider uppercase">ID: {teacher.id}</div>
                        </div>
                        <div className="flex items-center gap-2">
                          <div className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-black border transition-all ${subjectStyle.colors}`}>
                            {subjectStyle.icon}
                            <span>{teacher.subject}</span>
                          </div>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6 whitespace-nowrap">
                      <div className="space-y-2">
                        <div className="flex items-center gap-3 text-sm text-slate-600 font-bold group/mail">
                          <div className="p-2 bg-slate-100 rounded-xl group-hover/mail:bg-white group-hover/mail:shadow-sm transition-all border border-transparent group-hover/mail:border-slate-100">
                            <Mail size={16} className="text-slate-400 group-hover/mail:text-indigo-600" />
                          </div>
                          {teacher.email}
                        </div>
                        <div className="flex items-center gap-3 text-sm text-slate-600 font-bold group/phone" dir="ltr">
                          <div className="p-2 bg-slate-100 rounded-xl group-hover/phone:bg-white group-hover/phone:shadow-sm transition-all border border-transparent group-hover/phone:border-slate-100">
                            <Phone size={16} className="text-slate-400 group-hover/phone:text-indigo-600" />
                          </div>
                          {teacher.phone}
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6 whitespace-nowrap">
                      <div className="flex items-center justify-center gap-3">
                        <button className="p-3 text-slate-400 hover:text-indigo-600 hover:bg-white hover:shadow-md rounded-2xl transition-all border border-transparent hover:border-slate-100">
                          <Edit size={20} />
                        </button>
                        <button 
                          onClick={() => handleDeleteClick(teacher)}
                          className="p-3 text-slate-400 hover:text-red-600 hover:bg-white hover:shadow-md rounded-2xl transition-all border border-transparent hover:border-slate-100"
                        >
                          <Trash2 size={20} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        {filteredTeachers.length === 0 && (
          <div className="py-24 text-center">
            <div className="bg-slate-50 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6">
              <Search size={40} className="text-slate-200" />
            </div>
            <h3 className="text-xl font-bold text-slate-800">لا يوجد معلمين مطابقين</h3>
            <p className="text-slate-500 mt-2 font-medium">جرب البحث بكلمات أخرى أو أضف معلماً جديداً</p>
          </div>
        )}
      </div>

      {/* Add Teacher Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl animate-in zoom-in duration-300 overflow-hidden border border-white/20">
            <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-indigo-50/50">
              <div>
                <h3 className="text-3xl font-black text-slate-800">إضافة معلم</h3>
                <p className="text-indigo-600 font-bold text-sm mt-1 uppercase tracking-widest">New Staff Entry</p>
              </div>
              <button 
                onClick={() => setIsModalOpen(false)} 
                className="p-3 bg-white text-slate-400 hover:text-slate-600 rounded-2xl shadow-sm transition-all hover:rotate-90"
              >
                <X size={28} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-10 space-y-8">
              <div className="flex justify-center">
                <div className="relative group">
                  <img src={formData.photo} alt="Preview" className="w-32 h-32 rounded-[2.5rem] object-cover ring-8 ring-indigo-50 shadow-2xl group-hover:scale-105 transition-transform cursor-pointer" />
                  <button type="button" className="absolute -bottom-2 -right-2 p-3 bg-indigo-600 text-white rounded-2xl shadow-xl hover:bg-indigo-700 transition-all active:scale-90 border-4 border-white">
                    <Camera size={20} />
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-2">الاسم الكامل</label>
                  <input 
                    required
                    type="text" 
                    placeholder="مثال: أستاذ مراد"
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-[1.25rem] focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all font-bold"
                    value={formData.name}
                    onChange={e => setFormData({...formData, name: e.target.value})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-2">المادة الدراسية</label>
                  <input 
                    required
                    type="text" 
                    placeholder="مثال: رياضيات"
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-[1.25rem] focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all font-bold"
                    value={formData.subject}
                    onChange={e => setFormData({...formData, subject: e.target.value})}
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-2">البريد الإلكتروني</label>
                  <input 
                    required
                    type="email" 
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-[1.25rem] focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all text-left font-bold"
                    dir="ltr"
                    value={formData.email}
                    onChange={e => setFormData({...formData, email: e.target.value})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-700 mr-2">رقم الهاتف</label>
                  <input 
                    required
                    type="tel" 
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-[1.25rem] focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all text-left font-bold"
                    dir="ltr"
                    value={formData.phone}
                    onChange={e => setFormData({...formData, phone: e.target.value})}
                  />
                </div>
              </div>

              <div className="pt-4 flex gap-5">
                <button 
                  type="submit"
                  className="flex-1 bg-indigo-600 text-white py-5 rounded-[1.5rem] font-black text-lg hover:bg-indigo-700 transition-all shadow-2xl shadow-indigo-200 active:scale-95"
                >
                  حفظ البيانات
                </button>
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-10 py-5 bg-slate-100 text-slate-600 rounded-[1.5rem] font-black hover:bg-slate-200 transition-all"
                >
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {isDeleteModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-md shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner">
                <AlertTriangle size={40} />
              </div>
              <h3 className="text-2xl font-black text-slate-800 mb-2">تأكيد الحذف</h3>
              <p className="text-slate-500 font-medium mb-8">
                هل أنت متأكد من رغبتك في حذف المعلم <span className="font-bold text-slate-800">"{teacherToDelete?.name}"</span>؟ لا يمكن التراجع عن هذا الإجراء.
              </p>

              <div className="flex gap-4">
                <button 
                  onClick={confirmDelete}
                  className="flex-1 bg-red-600 text-white py-4 rounded-2xl font-black hover:bg-red-700 transition-all shadow-lg shadow-red-200 active:scale-95"
                >
                  تأكيد الحذف
                </button>
                <button 
                  onClick={() => setIsDeleteModalOpen(false)}
                  className="flex-1 bg-slate-100 text-slate-600 py-4 rounded-2xl font-black hover:bg-slate-200 transition-all active:scale-95"
                >
                  إلغاء
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TeacherList;

