                  <label className="text-xs font-black text-slate-500 mr-1 uppercase tracking-wider">تاريخ التعيين / التسجيل</label>
                  <div className="relative">
                    <Calendar size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                    <input 
                      required
                      type="date" 
                      className="w-full pl-12 pr-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all font-bold text-slate-700"
                      value={formData.registrationDate}
                      onChange={e => setFormData({...formData, registrationDate: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              {/* Footer Actions */}
              <div className="pt-6 flex gap-4">
                <button 
                  type="submit"
                  className="flex-1 bg-indigo-600 text-white py-5 rounded-2xl font-black text-lg hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-200 active:scale-95"
                >
                  إضافة المعلم للقاعدة
                </button>
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-10 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black hover:bg-slate-200 transition-all active:scale-95"
                >
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {isDeleteModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-md shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner">
                <AlertTriangle size={40} />
              </div>
              <h3 className="text-2xl font-black text-slate-800 mb-2">تأكيد الحذف</h3>
              <p className="text-slate-500 font-medium mb-8">
                هل أنت متأكد من رغبتك في حذف المعلم <span className="font-bold text-slate-800">"{teacherToDelete?.name}"</span>؟ لا يمكن التراجع عن هذا الإجراء.
              </p>

              <div className="flex gap-4">
                <button 
                  onClick={confirmDelete}
                  className="flex-1 bg-red-600 text-white py-4 rounded-2xl font-black hover:bg-red-700 transition-all shadow-lg shadow-red-200 active:scale-95"
                >
                  تأكيد الحذف
                </button>
                <button 
                  onClick={() => setIsDeleteModalOpen(false)}
                  className="flex-1 bg-slate-100 text-slate-600 py-4 rounded-2xl font-black hover:bg-slate-200 transition-all active:scale-95"
                >
                  إلغاء
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TeacherList;

import React, { useState } from 'react';
import { 
  Search, Plus, Edit, Trash2, Mail, Phone, BookOpen, X, Camera, User, 
  BadgeCheck, BookMarked, Calculator, Languages, Microscope, Palette, 
  Trophy, Map, BookText, GraduationCap, ShieldCheck, Music, AlertTriangle,
  ChevronDown, Calendar, Hash, ExternalLink, Info, Contact, ClipboardList,
  MessageSquare
} from 'lucide-react';
import { MOCK_TEACHERS } from '../constants';
import { Teacher } from '../types';

const TeacherList: React.FC = () => {
  const [teachers, setTeachers] = useState<Teacher[]>(MOCK_TEACHERS);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [teacherToDelete, setTeacherToDelete] = useState<Teacher | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    subject: '',
    email: '',
    phone: '',
    registrationDate: new Date().toISOString().split('T')[0],
    photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${Math.random()}`
  });

  const getSubjectStyle = (subject: string) => {
    const s = subject.toLowerCase();

    if (s.includes('رياضيات')) return { 
      icon: <Calculator size={14} />, 
      colors: 'bg-blue-50 text-blue-600 border-blue-100' 
    };
    if (s.includes('عربية')) return { 
      icon: <BookText size={14} />, 
      colors: 'bg-emerald-50 text-emerald-600 border-emerald-100' 
    };
    if (s.includes('فرنسية') || s.includes('إنجليزية')) return { 
      icon: <Languages size={14} />, 
      colors: 'bg-orange-50 text-orange-600 border-orange-100' 
    };
    if (s.includes('علمية') || s.includes('علوم') || s.includes('تكنولوجية')) return { 
      icon: <Microscope size={14} />, 
      colors: 'bg-indigo-50 text-indigo-600 border-indigo-100' 
    };
    if (s.includes('تشكيلية') || s.includes('فنية') || s.includes('رسم')) return { 
      icon: <Palette size={14} />, 
      colors: 'bg-pink-50 text-pink-600 border-pink-100' 
    };
    if (s.includes('موسيقية')) return { 
      icon: <Music size={14} />, 
      colors: 'bg-purple-50 text-purple-600 border-purple-100' 
    };
    if (s.includes('بدنية') || s.includes('رياضة')) return { 
      icon: <Trophy size={14} />, 
      colors: 'bg-red-50 text-red-600 border-red-100' 
    };
    if (s.includes('تاريخ') || s.includes('جغرافيا')) return { 
      icon: <Map size={14} />, 
      colors: 'bg-amber-50 text-amber-600 border-amber-100' 
    };
    if (s.includes('إسلامية')) return { 
      icon: <BookOpen size={14} />, 
      colors: 'bg-teal-50 text-teal-600 border-teal-100' 
    };
    if (s.includes('مدنية')) return { 
      icon: <ShieldCheck size={14} />, 
      colors: 'bg-cyan-50 text-cyan-600 border-cyan-100' 
    };

    return { 
      icon: <BookMarked size={14} />, 
      colors: 'bg-slate-50 text-slate-600 border-slate-100' 
    };
  };

  const filteredTeachers = teachers.filter(teacher => 
    teacher.name.includes(searchTerm) || teacher.subject.includes(searchTerm)
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newTeacher: Teacher = {
      id: `T${Math.floor(100 + Math.random() * 899)}`,
      ...formData
    };
    setTeachers([...teachers, newTeacher]);
    setIsModalOpen(false);
    setFormData({
      name: '',
      subject: '',
      email: '',
      phone: '',
      registrationDate: new Date().toISOString().split('T')[0],
      photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${Math.random()}`
    });
  };

  const handleDeleteClick = (e: React.MouseEvent, teacher: Teacher) => {
    e.stopPropagation();
    setTeacherToDelete(teacher);
    setIsDeleteModalOpen(true);
  };

  const confirmDelete = () => {
    if (teacherToDelete) {
      setTeachers(teachers.filter(t => t.id !== teacherToDelete.id));
      setIsDeleteModalOpen(false);
      setTeacherToDelete(null);
    }
  };

  const toggleExpand = (id: string) => {
