import React, { useState } from 'react';
import { 
  Search, Plus, Edit, Trash2, Mail, Phone, BookOpen, X, Camera, User, 
  BadgeCheck, BookMarked, Calculator, Languages, Microscope, Palette, 
  Trophy, Map, BookText, GraduationCap, ShieldCheck, Music, AlertTriangle,
  ChevronDown, Calendar, Hash, ExternalLink, Info, Contact, ClipboardList,
  MessageSquare
} from 'lucide-react';
import { MOCK_TEACHERS } from '../constants';
import { Teacher } from '../types';

const TeacherList: React.FC = () => {
  const [teachers, setTeachers] = useState<Teacher[]>(MOCK_TEACHERS);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [teacherToDelete, setTeacherToDelete] = useState<Teacher | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    subject: '',
    email: '',
    phone: '',
    registrationDate: new Date().toISOString().split('T')[0],
    photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${Math.random()}`
  });

  const getSubjectStyle = (subject: string) => {
    const s = subject.toLowerCase();

    // Mapping keywords to icons and colors
    if (s.includes('رياضيات')) return { 
      icon: <Calculator size={14} />, 
      colors: 'bg-blue-50 text-blue-600 border-blue-100 hover:bg-blue-100' 
    };
    if (s.includes('عربية') || s.includes('لغة')) {
        if (s.includes('عربية')) return { 
            icon: <BookText size={14} />, 
            colors: 'bg-emerald-50 text-emerald-600 border-emerald-100 hover:bg-emerald-100' 
        };
        return { 
            icon: <Languages size={14} />, 
            colors: 'bg-orange-50 text-orange-600 border-orange-100 hover:bg-orange-100' 
        };
    }
    if (s.includes('فرنسية') || s.includes('إنجليزية') || s.includes('لغات')) return { 
      icon: <Languages size={14} />, 
      colors: 'bg-orange-50 text-orange-600 border-orange-100 hover:bg-orange-100' 
    };
    if (s.includes('علمية') || s.includes('علوم') || s.includes('تكنولوجية') || s.includes('فيزياء')) return { 
      icon: <Microscope size={14} />, 
      colors: 'bg-indigo-50 text-indigo-600 border-indigo-100 hover:bg-indigo-100' 
    };
    if (s.includes('تشكيلية') || s.includes('فنية') || s.includes('رسم')) return { 
      icon: <Palette size={14} />, 
      colors: 'bg-pink-50 text-pink-600 border-pink-100 hover:bg-pink-100' 
    };
    if (s.includes('موسيقية') || s.includes('موسيقى')) return { 
      icon: <Music size={14} />, 
      colors: 'bg-purple-50 text-purple-600 border-purple-100 hover:bg-purple-100' 
    };
    if (s.includes('بدنية') || s.includes('رياضة')) return { 
      icon: <Trophy size={14} />, 
      colors: 'bg-red-50 text-red-600 border-red-100 hover:bg-red-100' 
    };
    if (s.includes('تاريخ') || s.includes('جغرافيا') || s.includes('اجتماعيات')) return { 
      icon: <Map size={14} />, 
      colors: 'bg-amber-50 text-amber-600 border-amber-100 hover:bg-amber-100' 
    };
    if (s.includes('إسلامية') || s.includes('دين')) return { 
      icon: <BookOpen size={14} />, 
      colors: 'bg-teal-50 text-teal-600 border-teal-100 hover:bg-teal-100' 
    };
    if (s.includes('مدنية')) return { 
      icon: <ShieldCheck size={14} />, 
      colors: 'bg-cyan-50 text-cyan-600 border-cyan-100 hover:bg-cyan-100' 
    };

    return { 
      icon: <BookMarked size={14} />, 
      colors: 'bg-slate-50 text-slate-600 border-slate-100 hover:bg-slate-100' 
    };
  };

  const filteredTeachers = teachers.filter(teacher => 
    teacher.name.includes(searchTerm) || teacher.subject.includes(searchTerm)
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newTeacher: Teacher = {
      id: `T${Math.floor(100 + Math.random() * 899)}`,
      ...formData
    };
    setTeachers([...teachers, newTeacher]);
    setIsModalOpen(false);
    setFormData({
      name: '',
      subject: '',
      email: '',
      phone: '',
      registrationDate: new Date().toISOString().split('T')[0],
      photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${Math.random()}`
    });
  };

  const handleDeleteClick = (e: React.MouseEvent, teacher: Teacher) => {
    e.stopPropagation();
    setTeacherToDelete(teacher);
    setIsDeleteModalOpen(true);
  };

  const confirmDelete = () => {
    if (teacherToDelete) {
      setTeachers(teachers.filter(t => t.id !== teacherToDelete.id));
      setIsDeleteModalOpen(false);
      setTeacherToDelete(null);
    }
  };

  const toggleExpand = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-700">
      <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 overflow-hidden">
        {/* Header Section */}
        <div className="p-8 border-b border-slate-100 flex flex-col sm:flex-row justify-between items-center gap-6 bg-gradient-to-l from-white to-slate-50/50">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-100">
              <User size={28} />
            </div>
            <div>
              <h2 className="text-2xl font-black text-slate-800">هيئة التدريس</h2>
              <p className="text-slate-500 text-sm font-medium">إدارة وتوجيه الكادر التعليمي للمدرسة</p>
            </div>
          </div>

          <div className="flex items-center gap-3 w-full sm:w-auto">
            <div className="relative flex-1 sm:w-72">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
              <input
                type="text"
                placeholder="ابحث عن اسم المعلم أو المادة..."
                className="w-full pr-12 pl-4 py-3 bg-white border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all shadow-sm font-medium"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <button 
              onClick={() => setIsModalOpen(true)}
              className="flex items-center gap-2 bg-indigo-600 text-white px-6 py-3 rounded-2xl hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-200 active:scale-95 whitespace-nowrap"
            >
              <Plus size={22} />
              <span className="font-bold">إضافة معلم</span>
            </button>
          </div>
        </div>

        {/* Table Section */}
        <div className="overflow-x-auto">
          <table className="w-full text-right border-collapse">
            <thead>
              <tr className="bg-slate-50/80 text-slate-500 text-xs font-bold uppercase tracking-widest border-b border-slate-100">
                <th className="px-8 py-5 text-right w-12"></th>
                <th className="px-4 py-5 text-right w-32">المعلم</th>
                <th className="px-8 py-5">المعلومات المهنية</th>
                <th className="px-8 py-5 text-center">التحكم</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredTeachers.map((teacher) => {
                const subjectStyle = getSubjectStyle(teacher.subject);
                const isExpanded = expandedId === teacher.id;
                return (
                  <React.Fragment key={teacher.id}>
                    <tr 
                      onClick={() => toggleExpand(teacher.id)}
                      className={`hover:bg-indigo-50/30 transition-all group cursor-pointer ${isExpanded ? 'bg-indigo-50/50' : ''}`}
                    >
                      <td className="px-8 py-6 text-center">
                        <ChevronDown 
                          size={20} 
                          className={`text-slate-400 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} 
                        />
                      </td>
                      <td className="px-4 py-6 whitespace-nowrap">
                        <div className="relative inline-block">
                          <img 
                            src={teacher.photo} 
                            alt={teacher.name} 
                            className="w-16 h-16 rounded-[1.25rem] object-cover ring-4 ring-white shadow-xl group-hover:scale-105 transition-transform duration-300"
                          />
                          <div className="absolute -top-2 -right-2 bg-emerald-500 text-white p-1 rounded-full border-4 border-white shadow-sm">
                            <BadgeCheck size={12} />
                          </div>
                        </div>
                      </td>
                      <td className="px-8 py-6 whitespace-nowrap">
                        <div className="flex flex-col gap-2">
                          <div className="font-black text-slate-800 text-lg group-hover:text-indigo-700 transition-colors leading-tight">
                            {teacher.name}
                          </div>
                          <div className="flex items-center gap-2">
                            <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl text-[11px] font-black border transition-all shadow-sm ${subjectStyle.colors}`}>
                              {subjectStyle.icon}
                              <span>{teacher.subject}</span>
                            </div>
                          </div>
                        </div>
                      </td>
                      <td className="px-8 py-6 whitespace-nowrap">
                        <div className="flex items-center justify-center gap-3">
                          <button 
                            onClick={(e) => { e.stopPropagation(); /* edit logic */ }}
                            className="p-3 text-slate-400 hover:text-indigo-600 hover:bg-white hover:shadow-md rounded-2xl transition-all border border-transparent hover:border-slate-100"
                          >
                            <Edit size={20} />
                          </button>
                          <button 
                            onClick={(e) => handleDeleteClick(e, teacher)}
                            className="p-3 text-slate-400 hover:text-red-600 hover:bg-white hover:shadow-md rounded-2xl transition-all border border-transparent hover:border-slate-100"
                          >
                            <Trash2 size={20} />
                          </button>
                        </div>
                      </td>
                    </tr>

                    {/* Expanded Content Area */}
                    {isExpanded && (
                      <tr className="bg-indigo-50/20 border-b border-indigo-100 animate-in slide-in-from-top-2 duration-300">
                        <td colSpan={4} className="px-8 md:px-12 py-8">
                          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            {/* ID & Date Section */}
                            <div className="space-y-4">
                              <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-indigo-100 flex items-center gap-4 group/card hover:border-indigo-300 transition-all">
                                <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl shadow-inner group-hover/card:bg-blue-600 group-hover/card:text-white transition-all">
                                  <Hash size={22} />
                                </div>
                                <div>
                                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-0.5">معرف المعلم</p>
                                  <p className="text-base font-black text-slate-800 tracking-wider">{teacher.id}</p>
                                </div>
                              </div>

                              <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-indigo-100 flex items-center gap-4 group/card hover:border-indigo-300 transition-all">
                                <div className="p-3 bg-emerald-50 text-emerald-600 rounded-2xl shadow-inner group-hover/card:bg-emerald-600 group-hover/card:text-white transition-all">
                                  <Calendar size={22} />
                                </div>
                                <div>
                                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-0.5">تاريخ الانضمام</p>
                                  <p className="text-base font-black text-slate-800">{teacher.registrationDate}</p>
                                </div>
                              </div>
                            </div>

                            {/* Contact Details - Visually Distinct Section */}
                            <div className="md:col-span-2 bg-white p-6 md:p-8 rounded-[2.5rem] shadow-sm border border-indigo-100 relative overflow-hidden group/contact hover:shadow-md transition-all">
                              <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50 rounded-full -mr-16 -mt-16 group-hover/contact:scale-110 transition-transform duration-500"></div>

                              <div className="relative flex items-center gap-3 mb-6">
                                <div className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-100">
                                  <Contact size={20} />
                                </div>
                                <h4 className="text-lg font-black text-slate-800">بيانات التواصل المباشر</h4>
                              </div>

                              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 relative">
                                {/* Email Card */}
                                <div className="p-5 bg-slate-50 rounded-3xl border border-slate-100 flex flex-col gap-3 group/item hover:bg-white hover:border-indigo-200 hover:shadow-sm transition-all">
                                  <div className="flex items-center justify-between">
                                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">البريد الإلكتروني</span>
                                    <Mail size={16} className="text-indigo-400 group-hover/item:text-indigo-600" />
                                  </div>
                                  <p className="text-sm font-black text-slate-700 truncate">{teacher.email}</p>
                                  <button className="text-[10px] font-bold text-indigo-600 flex items-center gap-1 hover:underline mt-1">
                                    <ExternalLink size={10} /> إرسال رسالة
                                  </button>
                                </div>

                                {/* Phone Card */}
                                <div className="p-5 bg-slate-50 rounded-3xl border border-slate-100 flex flex-col gap-3 group/item hover:bg-white hover:border-emerald-200 hover:shadow-sm transition-all">
                                  <div className="flex items-center justify-between">
                                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">رقم الهاتف</span>
                                    <Phone size={16} className="text-emerald-400 group-hover/item:text-emerald-600" />
                                  </div>
                                  <p className="text-lg font-black text-slate-700 tracking-[0.1em]" dir="ltr">{teacher.phone}</p>
                                  <button className="text-[10px] font-bold text-emerald-600 flex items-center gap-1 hover:underline mt-1">
                                    <MessageSquare size={10} /> واتساب
                                  </button>
                                </div>
                              </div>
                            </div>
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>

        {filteredTeachers.length === 0 && (
          <div className="py-24 text-center">
            <div className="bg-slate-50 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6">
              <Search size={40} className="text-slate-200" />
            </div>
            <h3 className="text-xl font-bold text-slate-800">لا يوجد معلمين مطابقين</h3>
            <p className="text-slate-500 mt-2 font-medium">جرب البحث بكلمات أخرى أو أضف معلماً جديداً</p>
          </div>
        )}
      </div>

      {/* Add Teacher Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl shadow-2xl animate-in zoom-in duration-300 overflow-hidden border border-white/20">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-indigo-50/50">
              <div>
                <h3 className="text-2xl font-black text-slate-800">إضافة معلم جديد</h3>
                <p className="text-indigo-600 font-bold text-xs mt-1 uppercase tracking-widest">New Staff Registration</p>
              </div>
              <button 
                onClick={() => setIsModalOpen(false)} 
                className="p-2.5 bg-white text-slate-400 hover:text-slate-600 rounded-2xl shadow-sm transition-all hover:rotate-90"
              >
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 space-y-10 max-h-[85vh] overflow-y-auto custom-scrollbar">
              {/* Profile Image Section */}
              <div className="flex justify-center mb-4">
                <div className="relative group">
                  <div className="w-28 h-28 rounded-[2rem] overflow-hidden ring-8 ring-indigo-50 shadow-2xl transition-transform group-hover:scale-105">
                    <img src={formData.photo} alt="Preview" className="w-full h-full object-cover" />
                  </div>
                  <button type="button" className="absolute -bottom-2 -right-2 p-3 bg-indigo-600 text-white rounded-2xl shadow-xl hover:bg-indigo-700 transition-all active:scale-90 border-4 border-white">
                    <Camera size={18} />
                  </button>
                </div>
              </div>

              {/* Basic Information Group */}
              <div className="space-y-6">
                <div className="flex items-center gap-3 pb-2 border-b border-slate-100">
                  <div className="p-2 bg-blue-50 text-blue-600 rounded-lg">
                    <Info size={18} />
                  </div>
                  <h4 className="font-black text-slate-800">المعلومات الأساسية</h4>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-500 mr-1 uppercase tracking-wider">الاسم الكامل</label>
                    <input 
                      required
                      type="text" 
                      placeholder="الأستاذ(ة)..."
                      className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all font-bold text-slate-700"
                      value={formData.name}
                      onChange={e => setFormData({...formData, name: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-500 mr-1 uppercase tracking-wider">المادة الدراسية</label>
                    <div className="relative">
                        <input 
                        required
                        type="text" 
                        placeholder="مثال: الرياضيات، التربية العلمية..."
