import React, { useState } from 'react';
import { 
  Search, Plus, Edit, Trash2, Mail, Phone, BookOpen, X, Camera, User, 
  BadgeCheck, BookMarked, Calculator, Languages, Microscope, Palette, 
  Trophy, Map, BookText, GraduationCap, ShieldCheck, Music, AlertTriangle,
  ChevronDown, Calendar, Hash, ExternalLink, Info, Contact, ClipboardList,
  MessageSquare, Atom, Globe, Key, RefreshCw, Copy, Check, FileDown
} from 'lucide-react';
import { MOCK_TEACHERS } from '../constants';
import { Teacher } from '../types';

const TeacherList: React.FC = () => {
  const [teachers, setTeachers] = useState<Teacher[]>(MOCK_TEACHERS);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [teacherToDelete, setTeacherToDelete] = useState<Teacher | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    subject: '',
    email: '',
    phone: '',
    registrationDate: new Date().toISOString().split('T')[0],
    apiKey: '',
    photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${Math.random()}`
  });

  const handleExportCSV = () => {
    // UTF-8 BOM for Arabic characters compatibility with Excel
    const BOM = '\uFEFF';
    const headers = ['الاسم', 'المادة', 'البريد الإلكتروني', 'رقم الهاتف'];
    const csvRows = [
      headers.join(','),
      ...filteredTeachers.map(teacher => [
        `"${teacher.name}"`,
        `"${teacher.subject}"`,
        `"${teacher.email}"`,
        `"${teacher.phone}"`
      ].join(','))
    ];

    const csvString = BOM + csvRows.join('\n');
    const blob = new Blob([csvString], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `قائمة_المعلمين_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const generateApiKey = () => {
    const randomPart = () => Math.random().toString(36).substring(2, 6).toUpperCase();
    const newKey = `SCH-${randomPart()}-${randomPart()}-${randomPart()}`;
    setFormData({ ...formData, apiKey: newKey });
  };

  const copyToClipboard = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const getSubjectStyle = (subject: string) => {
    const s = subject.toLowerCase();
    if (s.includes('رياضيات')) return { icon: <Calculator size={16} />, colors: 'bg-blue-50 text-blue-600 border-blue-100 ring-blue-500/10' };
    if (s.includes('عربية')) return { icon: <BookText size={16} />, colors: 'bg-emerald-50 text-emerald-600 border-emerald-100 ring-emerald-500/10' };
    if (s.includes('فرنسية') || s.includes('إنجليزية') || s.includes('لغات')) return { icon: <Languages size={16} />, colors: 'bg-orange-50 text-orange-600 border-orange-100 ring-orange-500/10' };
    if (s.includes('علمية') || s.includes('علوم')) return { icon: <Microscope size={16} />, colors: 'bg-indigo-50 text-indigo-600 border-indigo-100 ring-indigo-500/10' };
    if (s.includes('فنية') || s.includes('رسم')) return { icon: <Palette size={16} />, colors: 'bg-pink-50 text-pink-600 border-pink-100 ring-pink-500/10' };
    if (s.includes('موسيقى')) return { icon: <Music size={16} />, colors: 'bg-purple-50 text-purple-600 border-purple-100 ring-purple-500/10' };
    if (s.includes('رياضة')) return { icon: <Trophy size={16} />, colors: 'bg-red-50 text-red-600 border-red-100 ring-red-500/10' };
    return { icon: <BookMarked size={16} />, colors: 'bg-slate-50 text-slate-600 border-slate-100 ring-slate-500/10' };
  };

  const filteredTeachers = teachers.filter(teacher => 
