                                  <span className="flex items-center gap-2">
                                    <Hash size={12} /> رقم المعرف: {teacher.id}
                                  </span>
                                </div>
                              </div>
                            </div>
                          </td>
                        </tr>
                      )}
                    </React.Fragment>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={4} className="px-8 py-12 text-center">
                    <div className="flex flex-col items-center gap-3 text-slate-400">
                      <Search size={48} className="opacity-20" />
                      <p className="font-bold text-lg">لم يتم العثور على أي نتائج</p>
                      <button 
                        onClick={() => {setSearchTerm(''); setSelectedSubject('all');}}
                        className="text-indigo-600 font-bold hover:underline"
                      >
                        إعادة تعيين البحث
                      </button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl shadow-2xl animate-in zoom-in duration-300 overflow-hidden border border-white/20">
